import { cubicBezier, motion } from "framer-motion";
import React from "react";

interface MessageProps {
  message: {
    id: number;
    text: string;
    sender: "sender" | "receiver";
    time: string;
    file?: {
      name: string;
      type: string;
      url: string;
    } | null;
  };
  isOwnMessage: boolean;
}

const easing = cubicBezier(0.35, 0.17, 0.3, 0.86);

const Message: React.FC<MessageProps> = ({ message, isOwnMessage }) => {
 
  const isEmojiOnly = /^<img src=".*?" alt="emoji".*?>$/.test(message.text);

  return (
    <motion.div
      initial={{ opacity: 0, y: isOwnMessage ? 250 : -250, x: isOwnMessage ? -250 : 250 }}
      animate={{ opacity: 1, y: 0, x: 0 }}
      transition={{ duration: 0.5, ease: "linear" }}
      className={`flex flex-col relative w-full ${isOwnMessage ? "justify-end items-end" : "justify-start items-start"} my-2`}
    >
       
      {isEmojiOnly ? (
   
        <div className="">
          <span
            dangerouslySetInnerHTML={{ __html: message.text }}
            className="w-20 h-20 block object-cover"
          ></span>
        </div>
      ) : (
       
        <div className={`p-3 w-fit rounded-lg max-w-[75%] shadow-md ${
          isOwnMessage ? "bg-blue-500 self-end text-white" : "bg-gray-200 text-black"
        }`}>
          <p className="text-sm" dangerouslySetInnerHTML={{ __html: message.text }}></p>
        </div>
      )}
      <p className="text-xs text-gray-300 mt-1 text-right">{message.time}</p>
    </motion.div>
  );
};

export default Message;
