import { Avatar, AvatarImage } from "@/components/ui/avatar";
import { Dialog, Transition } from "@headlessui/react";
import { Fragment, useState } from "react";
import IconButton from "./Icon";
import VideoCallModal from "./VideoCallModal";
import VoiceCallModal from "./VoiceCallModal";

interface HeaderProps {
  conversation: {
    avatar: string;
    name: string;
    lastSeen?: string;
  };
}

const Header: React.FC<HeaderProps> = ({ conversation }) => {
  if (!conversation) return null;

  const [isOpenVideoModal, setIsOpenVideoModal] = useState<boolean>(false);
  const [isOpenVoiceModal, setIsOpenVoiceModal] = useState<boolean>(false);

  return (
    <>
      <div className="py-3 px-8 glassBg border-b border-gray-700 shadow-lg backdrop-blur-md">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <Avatar className="w-14 h-14 border-[3px] p-[2px] bg-gradient-to-r from-blue-500 to-indigo-600 rounded-full">
              <div className="w-full h-full bg-black rounded-full p-[2px]">
                <AvatarImage
                  src={conversation.avatar}
                  className="w-full h-full object-cover rounded-full"
                  alt={conversation.name}
                />
              </div>
            </Avatar>
            <div>
              <h4 className="text-lg text-white font-semibold">
                {conversation.name}
              </h4>
              <span className="text-sm text-gray-400">
                {conversation.lastSeen || "Last Seen Now"}
              </span>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <IconButton
              name="FaPhoneAlt"
              size={18}
              onClick={() => setIsOpenVoiceModal(true)}
            />
            <VoiceCallModal
              isOpenVoiceModal={isOpenVoiceModal}
              setIsOpenVoiceModal={setIsOpenVoiceModal}
            />
            <IconButton
              name="FaVideo"
              size={18}
              onClick={() => setIsOpenVideoModal(true)}
            />
            <VideoCallModal
              isOpen={isOpenVideoModal}
              setIsOpen={setIsOpenVideoModal}
            />
            <IconButton name="FaInfo" size={18} />
          </div>
        </div>
      </div>
    </>
  );
};

export default Header;
